{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is disabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable detailed monitoring, reducing the granularity of CloudWatch metrics available for security monitoring and incident investigation."
    },
    {
      "check_id": "CKV_AWS_135",
      "title": "EC2 instance is not EBS optimized",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable EBS optimization. The instance type is changed to a compatible equivalent and EBS optimization is explicitly enabled."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 permits Instance Metadata Service Version 1",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "No metadata options require session tokens, so the instance can accept IMDSv1 requests, increasing the risk of credential theft through server-side request forgery."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root volume encryption is not enforced",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The root EBS volume does not explicitly enable encryption, so data at rest may be created without encryption depending on account-level defaults."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "EC2 instance has no IAM role",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance has no IAM instance profile, preventing workloads from using scoped, automatically rotated AWS credentials. A role with no permissions by default is attached so required permissions can be granted explicitly later."
    }
  ],
  "patched_code": "resource "aws_iam_role" "levelup_instance" {
  name_prefix = "levelup-instance-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "levelup_instance" {
  name_prefix = "levelup-instance-"
  role        = aws_iam_role.levelup_instance.name
}

resource "aws_instance" "MyFirstInstnace" {
  ami                    = lookup(var.AMIS, var.AWS_REGION)
  instance_type          = "t3.micro"
  availability_zone      = "us-east-2a"
  key_name               = aws_key_pair.levelup_key.key_name
  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]
  subnet_id              = aws_subnet.levelupvpc-public-1.id
  iam_instance_profile   = aws_iam_instance_profile.levelup_instance.name
  monitoring             = true
  ebs_optimized          = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted = true
  }
}
",
  "fix_summary": "Enabled detailed monitoring, EBS optimization, root-volume encryption, and IMDSv2 enforcement. Changed the instance to the EBS-optimization-compatible t3.micro type and attached a least-privilege IAM role with no permissions by default."
}
